-- 121: Original BrillaPrep WASSCE Commerce Detailed Syllabus beta questions, part 2.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_011', 'topic_was_commerce_3', 'subj_wassce_commerce', 'exam_wassce', 'What is the basic difference between wholesale and retail trade?', 'multiple_choice', '["A. Retailers always manufacture every item they sell","B. Wholesalers sell only services","C. Wholesalers mainly sell in bulk to businesses, while retailers sell to final consumers","D. There is no difference in the customers they serve"]', 'C', 'Wholesalers commonly break the production-to-retail gap by buying large quantities, while retailers make suitable quantities available to final users. Therefore the correct answer is C: Wholesalers mainly sell in bulk to businesses, while retailers sell to final consumers.', 'medium', 1, 1, 90, 'st_was_commerce_3', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_012', 'topic_was_commerce_3', 'subj_wassce_commerce', 'exam_wassce', 'Which document sent by a seller shows goods supplied and the amount due?', 'multiple_choice', '["A. Enquiry","B. Debit card","C. Certificate of origin","D. Invoice"]', 'D', 'An invoice itemises goods, quantities, prices, discounts and the total payable, creating a commercial record of the credit sale. Therefore the correct answer is D: Invoice.', 'hard', 2, 2, 90, 'st_was_commerce_3', 'Explain', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_013', 'topic_was_commerce_3', 'subj_wassce_commerce', 'exam_wassce', 'What does a bill of lading mainly provide in sea transport?', 'multiple_choice', '["A. Evidence of receipt, carriage terms and title to shipped goods","B. A retail price list","C. A licence to operate a bank","D. A guarantee that goods cannot be damaged"]', 'A', 'The carrier issues a bill of lading as a receipt and contract evidence, and the document can represent title to the specified goods. Therefore the correct answer is A: Evidence of receipt, carriage terms and title to shipped goods.', 'easy', 1, 1, 90, 'st_was_commerce_3', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_014', 'topic_was_commerce_3', 'subj_wassce_commerce', 'exam_wassce', 'Why may a producer use an agent in a foreign market?', 'multiple_choice', '["A. The agent eliminates exchange-rate risk completely","B. The agent can provide local market knowledge and arrange sales","C. The agent becomes the automatic owner of the factory","D. The agent makes customs rules irrelevant"]', 'B', 'An agent can locate buyers, negotiate and advise on local practices for a commission, while ownership and commercial risk remain governed by the agreement. Therefore the correct answer is B: The agent can provide local market knowledge and arrange sales.', 'medium', 2, 2, 90, 'st_was_commerce_3', 'Explain', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_015', 'topic_was_commerce_3', 'subj_wassce_commerce', 'exam_wassce', 'What is a major function of a wholesaler for a manufacturer?', 'multiple_choice', '["A. Selling only one unit at a time to every consumer","B. Preventing products from reaching retailers","C. Buying large quantities and reducing the manufacturer’s storage burden","D. Setting national taxation policy"]', 'C', 'By purchasing in bulk and holding stock, wholesalers help manufacturers maintain production and reach many retailers through fewer transactions. Therefore the correct answer is C: Buying large quantities and reducing the manufacturer’s storage burden.', 'hard', 3, 3, 90, 'st_was_commerce_3', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_016', 'topic_was_commerce_4', 'subj_wassce_commerce', 'exam_wassce', 'Which mode is generally most suitable for moving bulky low-value goods over a long international route?', 'multiple_choice', '["A. Courier motorcycle","B. Air freight","C. Hand delivery","D. Sea transport"]', 'D', 'Sea transport has high capacity and relatively low unit cost for bulky cargo, although it is slower than air transport. Therefore the correct answer is D: Sea transport.', 'easy', 2, 2, 90, 'st_was_commerce_4', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_017', 'topic_was_commerce_4', 'subj_wassce_commerce', 'exam_wassce', 'What is the commercial benefit of warehousing seasonal goods?', 'multiple_choice', '["A. Supply can be held and released when consumers require it","B. Storage makes every product improve with age","C. Warehousing removes all insurance needs","D. Goods can no longer lose value"]', 'A', 'Warehousing balances production and consumption across time, but stock must still be protected, recorded and managed against damage or obsolescence. Therefore the correct answer is A: Supply can be held and released when consumers require it.', 'medium', 1, 1, 90, 'st_was_commerce_4', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_018', 'topic_was_commerce_4', 'subj_wassce_commerce', 'exam_wassce', 'Why is containerisation important in international trade?', 'multiple_choice', '["A. Containers remove the need for documentation","B. Standard containers reduce repeated handling and support intermodal transport","C. Every container can carry any hazardous product without rules","D. Containers guarantee zero theft"]', 'B', 'A sealed standard unit can transfer between ship, rail and road more efficiently, lowering handling time and some loss risks. Therefore the correct answer is B: Standard containers reduce repeated handling and support intermodal transport.', 'hard', 2, 2, 90, 'st_was_commerce_4', 'Explain', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_019', 'topic_was_commerce_4', 'subj_wassce_commerce', 'exam_wassce', 'Which communication method provides a durable formal record of agreed contract terms?', 'multiple_choice', '["A. An unrecorded casual conversation","B. A rumour from a third party","C. A signed written or authenticated electronic document","D. An anonymous verbal message"]', 'C', 'A retained, attributable document allows the parties to review what was offered and accepted and can support audit or dispute resolution. Therefore the correct answer is C: A signed written or authenticated electronic document.', 'easy', 1, 1, 90, 'st_was_commerce_4', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_020', 'topic_was_commerce_4', 'subj_wassce_commerce', 'exam_wassce', 'What is an important consideration when choosing transport for perishable goods?', 'multiple_choice', '["A. Only the colour of the vehicle","B. The driver’s favourite route regardless of time","C. Whether the goods need no handling","D. Speed and the availability of suitable temperature control"]', 'D', 'Perishables can deteriorate quickly, so delivery time, refrigeration, reliability, cost and product value must be balanced. Therefore the correct answer is D: Speed and the availability of suitable temperature control.', 'medium', 3, 3, 90, 'st_was_commerce_4', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-expansion-beta-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published WAEC Ghana Commerce syllabus; not official WAEC examination material.', 'https://waecgh.org/wp-content/uploads/2024/07/COMMERCE.pdf', 0, 1 FROM questions WHERE id BETWEEN 'q_was_commerce_b001_011' AND 'q_was_commerce_b001_020';
